svg.script:
(function () {
  var XHTML = 'http://www.w3.org/1999/xhtml';
  var svgCreate = document.createElement.bind(document);
  document.createElement = function (tag) {
    try { return document.createElementNS(XHTML, tag); }
    catch (e) { return svgCreate(tag); }
  };

  var body = document.getElementById('svg-body');
  if (body) {
    try {
      Object.defineProperty(document, 'body', {
        configurable: true,
        get: function () { return body; }
      });
    } catch (e) {}
  }
})();

function handleProjectChange() {
  const select = document.getElementById('projectSelect');
  const customContainer = document.getElementById('customPathContainer');

  if (select.value === 'CUSTOM') {
    customContainer.classList.remove('hidden');
  } else {
    customContainer.classList.add('hidden');
  }
}

async function launchSite(openInNewTab) {
  const projectSelect = document.getElementById('projectSelect');
  const customInput = document.getElementById('customPathInput');
  const mirrorSelect = document.getElementById('mirrorSelect');

  let targetPath = projectSelect.value;
  if (targetPath === 'CUSTOM') {
    targetPath = customInput.value.trim();
    if (!targetPath) {
      alert('Please enter a valid custom GitHub path or URL!');
      return;
    }
  }

  let fullFetchUrl = '';
  if (targetPath.startsWith('http://') || targetPath.startsWith('https://')) {
    fullFetchUrl = targetPath;
  } else {
    const mirrorBase = mirrorSelect.value;
    const cleanPath = targetPath.startsWith('/') ? targetPath : '/' + targetPath;
    fullFetchUrl = mirrorBase + cleanPath + '?t=' + Date.now();
  }

  const addressBar = document.getElementById('previewAddressBar');
  addressBar.textContent = fullFetchUrl;

  if (openInNewTab) {
    const targetTab = window.open('about:blank', '_blank');

    try {
      const response = await fetch(fullFetchUrl);
      if (!response.ok) throw new Error('HTTP Status ' + response.status);
      const htmlContent = await response.text();

      targetTab.document.open();
      targetTab.document.write(htmlContent);
      targetTab.document.close();
    } catch (err) {
      showTabError(targetTab, fullFetchUrl, err.message);
    }
  } else {
    showState('loading');

    try {
      const response = await fetch(fullFetchUrl);
      if (!response.ok) throw new Error('HTTP Status ' + response.status);
      const htmlContent = await response.text();

      const frame = document.getElementById('inlineFrame');
      showState('frame');

      const frameDoc = frame.contentWindow.document;
      frameDoc.open();
      frameDoc.write(htmlContent);
      frameDoc.close();
    } catch (err) {
      showState('idle');
      alert('Failed to load content via inline fetch: ' + err.message + '\n\nTry opening in a new tab or selecting a different CDN node.');
    }
  }
}

function showState(state) {
  const idleState = document.getElementById('idleState');
  const loadingState = document.getElementById('loadingState');
  const frame = document.getElementById('inlineFrame');

  idleState.classList.add('hidden');
  loadingState.classList.add('hidden');
  frame.classList.add('hidden');

  if (state === 'idle') idleState.classList.remove('hidden');
  if (state === 'loading') loadingState.classList.remove('hidden');
  if (state === 'frame') frame.classList.remove('hidden');
}

function clearPreview() {
  showState('idle');
  document.getElementById('previewAddressBar').textContent = 'about:blank';
  const frame = document.getElementById('inlineFrame');
  frame.src = 'about:blank';
}

function showTabError(targetTab, url, errorMsg) {
  if (!targetTab) return;
  targetTab.document.open();
  targetTab.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <title>Launch Error</title>
      <style>
        body { background: #0b0f19; color: #fff; font-family: system-ui, sans-serif; display: flex; align-items: center; justify-content: center; min-height: 100vh; margin: 0; padding: 20px; text-align: center; }
        .card { background: #111827; border: 1px solid #1f2937; border-radius: 12px; padding: 32px; max-width: 480px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); }
        h2 { color: #f43f5e; margin-top: 0; }
        p { color: #9ca3af; font-size: 14px; line-height: 1.5; }
        code { background: #1f2937; padding: 2px 6px; border-radius: 4px; color: #38bdf8; word-break: break-all; }
      </style>
    </head>
    <body>
      <div class="card">
        <h2>Failed to Fetch Resource</h2>
        <p>Could not load source from:</p>
        <p><code>${url}</code></p>
        <p><b>Error Details:</b> ${errorMsg}</p>
        <p style="margin-top:20px; font-size:12px; color:#6b7280;">Try returning to the dashboard and picking another mirror node.</p>
      </div>
    </body>
    </html>
  `);
  targetTab.document.close();
}
